'use strict';

// MODULES //

var isObject = require( '@stdlib/assert/is-object' );
var ArcEncodingSet = require( '@stdlib/plot/vega/mark/arc/encoding-set' );


// MAIN //

/**
* Tests whether an input value is an arc mark encoding set.
*
* @param {*} value - value to test
* @returns {boolean} boolean indicating whether an input value is an arc mark encoding set
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
* var ArcEncodingSet = require( '@stdlib/plot/vega/mark/arc/encoding-set' );
*
* var v = new ArcEncodingSet({
*     'x': new Value({
*         'field': 'x',
*         'scale': 'xScale'
*     })
* });
* var bool = isArcMarkEncodingSet( v );
* // returns true
*
* bool = isArcMarkEncodingSet( {} );
* // returns false
*
* bool = isArcMarkEncodingSet( 'foo' );
* // returns false
*/
function isArcMarkEncodingSet( value ) {
	return (
		value instanceof ArcEncodingSet ||

		// The following is a set of rather imperfect heuristics for handling instances originating in a different realm...
		(
			isObject( value ) &&
			value.constructor.name === 'ArcEncodingSet'
		)
	);
}


// EXPORTS //

module.exports = isArcMarkEncodingSet;
